    if n < 0:
        raise ValueError("n must not be negative")
    if width < 1:
        raise ValueError("width must be at least 1")
    digits = []
    while n:
        n, r = divmod(n, 32)
        digits.append(ALPHABET[r])
    text = "".join(reversed(digits))
    return text.rjust(width, ALPHABET[0])


def decode_int(text):
    syms = _symbols(text)
    if not syms:
        raise ValueError("empty code")
    n = 0
    for c in syms:
        n = n * 32 + _VALUE[c]
    return n


